import java.util.concurrent.atomic.AtomicInteger;

class Demo {
    public static void main(String[] args) {
        AtomicInteger finished = new AtomicInteger();

        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {   // one virtual thread per task
            for (int i = 0; i < 10_000; i++) {
                executor.submit(() -> {
                    Thread.sleep(Duration.ofMillis(100));                      // waiting does not block a core
                    finished.incrementAndGet();
                    return null;
                });
            }
        }                                                                      // close() waits for all tasks

        System.out.println(finished.get() + " tasks finished");
    }
}

