class Account {
    final long balance;
    Account(long balance) { this.balance = balance; }
}

class Savings extends Account {
    Savings(long deposit) {
        if (deposit < 0) throw new IllegalArgumentException("deposit must not be negative");   // before super
        long bonus = deposit / 10;
        super(deposit + bonus);
    }
}

class Demo {
    public static void main(String[] args) {
        System.out.println(new Savings(1_000).balance);
        try {
            new Savings(-5);
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }
}

